from pathlib import Path

css = "/* QH DESIGN PASS 106 — unified Egyptian café visual language */\n:root{--qh-bg:#101a16;--qh-surface:#1b2a22;--qh-surface2:#24372b;--qh-ivory:#f2e8d4;--qh-muted:#b9ad96;--qh-brass:#c49a5b;--qh-brass2:#e0c28d;--qh-line:rgba(196,154,91,.28);--qh-shadow:0 14px 34px rgba(0,0,0,.28)}\nhtml,body{background:radial-gradient(ellipse at 50% -15%,#344b39 0,#1a2a21 42%,#101813 100%)!important;color:var(--qh-ivory)!important}\n#app{background:transparent!important}\n.start.neo-home.qh-experience{box-sizing:border-box;width:min(100%,620px);min-height:100dvh;margin:0 auto;padding:clamp(12px,3.5vw,24px) clamp(12px,4vw,22px) 28px!important;background:transparent!important;color:var(--qh-ivory)!important;font-family:'Cairo',system-ui,sans-serif;position:relative;overflow:hidden}\n.qh-topline{display:flex;align-items:center;justify-content:space-between;gap:14px;margin:0 auto 15px;max-width:560px}\n.qh-brand-sign{position:relative;display:grid;grid-template-columns:54px auto;grid-template-rows:auto auto;align-items:center;column-gap:9px;color:#e5c994;min-width:0}\n.qh-sign-art{width:54px;height:50px;grid-row:1/3;filter:drop-shadow(0 3px 5px #0007)}\n.qh-sign-ar{font-size:19px;font-weight:900;line-height:1.2;white-space:nowrap;letter-spacing:-.5px}\n.qh-sign-sub{font-size:9px;letter-spacing:1.5px;color:#b9a47e;white-space:nowrap}\n.qh-powered{display:flex;flex-direction:column;align-items:flex-end;gap:0;padding:5px 0 5px 12px;border-left:1px solid var(--qh-line);line-height:1.15;flex-shrink:0}\n.qh-powered span,.qh-powered i{font:700 8px/1.4 system-ui,sans-serif;letter-spacing:1.7px;color:#a99a7c}\n.qh-powered b{font:800 17px/1.25 system-ui,sans-serif;color:#f0d6a4;letter-spacing:-.3px}\n.qh-powered i{font-style:normal;font-size:7px;color:#8e9b88}\n.qh-hero{position:relative;display:flex;align-items:center;justify-content:space-between;gap:10px;min-height:128px;padding:22px 21px 26px!important;margin:0 0 14px;border:1px solid rgba(208,174,116,.36)!important;border-radius:19px!important;background:linear-gradient(115deg,rgba(44,73,53,.98),rgba(24,43,32,.98) 70%)!important;box-shadow:inset 0 1px rgba(255,255,255,.08),var(--qh-shadow)!important;overflow:hidden}\n.qh-hero:before{content:\"\";position:absolute;width:220px;height:220px;border:1px solid rgba(218,188,135,.12);border-radius:50%;right:-105px;top:-75px;box-shadow:0 0 0 15px rgba(218,188,135,.025),0 0 0 34px rgba(218,188,135,.02)}\n.qh-hero:after{content:\"\";position:absolute;inset:auto 20px 12px;height:1px;background:linear-gradient(90deg,transparent,rgba(218,188,135,.5),transparent)}\n.qh-hero-copy{position:relative;z-index:1}\n.qh-eyebrow{font-size:10px;font-weight:800;color:#d7bc8b;letter-spacing:.7px}\n.qh-hero h1{margin:4px 0 2px!important;color:#f5e8d0!important;font-size:clamp(26px,7vw,37px)!important;line-height:1.3!important;font-weight:900!important;letter-spacing:-1px;text-shadow:0 2px 10px #0006}\n.qh-hero p{margin:2px 0 0!important;color:#c8c0a9!important;font-size:12px!important}\n.qh-hero-seal{z-index:1;display:flex;flex-direction:column;align-items:center;justify-content:center;width:76px;height:76px;flex:0 0 76px;border:1px solid rgba(224,194,141,.55);border-radius:50%;outline:1px solid rgba(224,194,141,.22);outline-offset:4px;color:#e7c991;background:rgba(11,24,17,.22);transform:rotate(-7deg)}\n.qh-hero-seal span{font-size:9px;color:#c4b28d}.qh-hero-seal b{font-size:18px;line-height:1.2}.qh-hero-seal small{font:700 7px system-ui;letter-spacing:1.2px;color:#a9956d}\n.qh-hero-rule{position:absolute;bottom:7px;left:22px;right:22px;display:flex;align-items:center;gap:7px;color:#c49a5b;font-size:8px}.qh-hero-rule i{height:1px;flex:1;background:linear-gradient(90deg,transparent,#c49a5b88,transparent)}\n.qh-stepper{display:flex;align-items:center;justify-content:center;gap:12px;margin:0 auto 15px;max-width:410px;padding:9px 13px;border-bottom:1px solid rgba(196,154,91,.18)}\n.qh-stepper>div{display:flex;align-items:center;gap:7px;color:#8e998c;font-size:11px;font-weight:700;white-space:nowrap}\n.qh-stepper>div b{display:grid;place-items:center;width:24px;height:24px;border:1px solid #56624e;border-radius:50%;font:700 9px system-ui;color:#aeb49f}\n.qh-stepper>div.active{color:#f0d9ae}.qh-stepper>div.active b{background:#c49a5b;border-color:#e1c18a;color:#172219;box-shadow:0 0 0 3px #c49a5b25}\n.qh-stepper>i{height:1px;width:45px;background:linear-gradient(90deg,#6e785d,#bd955a)}\n.qh-panel{position:relative;margin:0 0 13px;padding:17px 16px 16px!important;border:1px solid rgba(196,154,91,.24)!important;border-radius:17px!important;background:linear-gradient(145deg,rgba(34,53,41,.98),rgba(23,38,29,.98))!important;box-shadow:0 8px 22px rgba(0,0,0,.18)!important}\n.qh-section-title{display:flex;align-items:center;gap:10px;margin:0 0 16px}\n.qh-index{display:grid;place-items:center;flex:0 0 34px;height:34px;border:1px solid rgba(207,170,108,.55);border-radius:11px;background:rgba(196,154,91,.12);color:#e4c48d;font:800 11px system-ui}\n.qh-section-title h3,.qh-character-head h3{margin:0!important;color:#f0e3c9!important;font-size:15px!important;font-weight:900!important;line-height:1.45}\n.qh-section-title p,.qh-character-head p{margin:1px 0 0!important;color:#aeb39e!important;font-size:10px!important}\n.qh-section-tag{margin-right:auto;color:#82917c;font:700 7px system-ui;letter-spacing:1.1px}\n.qh-field-label{display:block;margin:0 0 7px;color:#d8c7a5;font-size:11px;font-weight:800}\n.qh-input-wrap{position:relative}\n.qh-input-icon{position:absolute;right:13px;top:50%;transform:translateY(-50%);color:#c49a5b;z-index:1}\n.qh-name-input{box-sizing:border-box;width:100%;height:49px;padding:0 37px 0 13px!important;border:1px solid #806b49!important;border-radius:11px!important;background:#111f18!important;color:#f3e8d3!important;font-size:14px!important;box-shadow:inset 0 2px 6px #0003!important}\n.qh-name-input:focus{outline:2px solid rgba(210,173,110,.35);border-color:#d0ad6e!important}\n.qh-id-row{display:flex;align-items:center;justify-content:space-between;gap:10px;margin:10px 0 13px;padding:10px 11px;border:1px solid rgba(196,154,91,.18);border-radius:10px;background:rgba(9,20,14,.3)}\n.qh-id-row>div{display:flex;flex-direction:column;gap:2px;min-width:0}.qh-id-row small{font:700 8px system-ui;letter-spacing:1.5px;color:#9b9b80}.qh-id-row b{font:700 10px system-ui;color:#e1d1b1;overflow-wrap:anywhere}\n.qh-copy-id{border:1px solid #796545;border-radius:8px;padding:7px 9px;background:#26392b;color:#e5d2aa;font-size:10px;font-weight:800;white-space:nowrap}\n.qh-google-login{display:flex;align-items:center;gap:11px;width:100%;padding:11px 13px;border:1px solid rgba(223,195,148,.55);border-radius:11px;background:linear-gradient(110deg,#f0e8d9,#d9cbb1);color:#1e2c22;text-align:right}\n.qh-google-g{display:grid;place-items:center;width:31px;height:31px;border-radius:9px;background:#fff;color:#4285f4;font:900 18px Arial;box-shadow:0 2px 6px #0002}\n.qh-google-login>span:nth-child(2){display:flex;flex-direction:column;flex:1}.qh-google-login b{font-size:12px}.qh-google-login small{font-size:9px;color:#5e665b}.qh-google-login i{font-style:normal;font-size:17px}\n.qh-login-note{margin:7px 2px 14px;color:#929d8d;font-size:9px;text-align:center}\n.qh-account-state{display:flex;align-items:center;gap:9px;margin:0 0 14px;padding:10px;border:1px solid #63866a66;border-radius:10px;background:#2c503322}.qh-account-state>span{display:grid;place-items:center;width:24px;height:24px;border-radius:50%;background:#476e4d;color:#fff}.qh-account-state div{display:flex;flex-direction:column}.qh-account-state b{font-size:11px;color:#dce9d5}.qh-account-state small{font-size:9px;color:#aab9a1}\n.qh-character-head{display:flex;align-items:center;justify-content:space-between;margin:16px 0 9px;padding-top:13px;border-top:1px solid rgba(196,154,91,.18)}.qh-character-head>span{color:#d4b47d;font:800 11px system-ui}\n.qh-avatar-pick{display:grid!important;grid-template-columns:repeat(auto-fit,minmax(58px,1fr));gap:8px!important}\n.qh-avatar-pick button{display:flex!important;flex-direction:column;align-items:center;justify-content:center;gap:3px;min-width:0;min-height:72px;padding:7px 3px!important;border:1px solid #65705b!important;border-radius:12px!important;background:linear-gradient(145deg,#2a4030,#1a2b20)!important;color:#e8dcc4!important;transition:transform .15s,border-color .15s,background .15s}\n.qh-avatar-pick button.on{border:1px solid #e0c28d!important;background:linear-gradient(145deg,#526344,#334a34)!important;box-shadow:0 0 0 2px rgba(224,194,141,.18),0 5px 12px #0003!important;transform:translateY(-2px)}\n.qh-avatar-art{font-size:27px;line-height:1.2}.qh-avatar-pick button small{font-size:8px;color:#c5b997}\n.qh-bottom-actions{display:flex;flex-direction:column;gap:8px;margin:13px 0 0}\n.qh-step-caption{text-align:center;color:#9ca58f;font-size:10px}\n.qh-primary{width:100%;min-height:49px;padding:11px 17px!important;border:1px solid #f0d5a0!important;border-radius:11px!important;background:linear-gradient(110deg,#e4c58c,#b98a4c)!important;color:#211e15!important;font-size:14px!important;font-weight:900!important;box-shadow:0 6px 15px #0004,inset 0 1px #fff8!important}\n.qh-primary span{display:inline-block;margin-right:8px;font-size:18px;vertical-align:-1px}\n.qh-two-actions{flex-direction:row}.qh-two-actions .qh-primary{flex:1}.qh-back{min-width:92px;border:1px solid #806b49!important;border-radius:11px!important;background:#26392b!important;color:#e6d6b6!important}\n.qh-mode-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}\n.qh-mode-card{position:relative;display:flex;flex-direction:column;align-items:flex-start;gap:5px;min-height:111px;padding:12px 10px!important;border:1px solid #586852;border-radius:13px;background:linear-gradient(145deg,#2a4030,#1b2c21);color:#e8dfca;text-align:right}\n.qh-mode-card.selected{border-color:#dfbd82;background:linear-gradient(145deg,#425c3e,#263e2d);box-shadow:inset 0 0 0 1px #dfbd8244,0 5px 14px #0003}\n.qh-mode-symbol{display:grid;place-items:center;width:31px;height:31px;border-radius:9px;background:#c49a5b20;color:#e0c18b;font-size:19px}\n.qh-mode-card b{font-size:11px}.qh-mode-card small{font-size:9px;color:#aeb39e}.qh-mode-card i{position:absolute;left:9px;top:9px;font-style:normal;color:#d9bd88;font-size:12px}\n.qh-games-grid{grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}\n.qh-game-card{display:flex!important;flex-direction:column;align-items:center;justify-content:center;gap:5px;min-height:103px;padding:10px 5px!important;border:1px solid #5e6b57!important;border-radius:13px!important;background:linear-gradient(145deg,#2c4332,#1c2e22)!important;color:#f0e5ce!important}\n.qh-game-card>b{font-size:27px;line-height:1.2}.qh-game-card strong{font-size:12px!important;color:#f2e5ce!important}.qh-game-card small{font-size:9px!important;color:#b6b89f!important}\n.qh-game-card.on{border-color:#e0c28d!important;background:linear-gradient(145deg,#4a6140,#293f2d)!important;box-shadow:0 0 0 2px #e0c28d26,0 5px 12px #0003!important}\n.qh-game-card.off{opacity:.5;filter:saturate(.55)}\n.qh-stake-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:7px}\n.qh-stake-opt{min-height:48px;border:1px solid #65735a!important;border-radius:10px!important;background:#263c2b!important;color:#eee0c4!important}.qh-stake-opt.on{border-color:#e1c28d!important;background:#4b6340!important}\n.qh-stake-opt b{font-size:15px}.qh-stake-opt small{font-size:9px}\n.qh-stake-summary{color:#c4b99e!important;font-size:10px}.qh-stake-summary b{color:#edcf98!important}\n.qh-difficulty-panel .difficulty-grid{gap:7px}.qh-difficulty-panel .difficulty-opt{border-radius:10px!important;background:#263c2b!important;color:#e9dec7!important}.qh-difficulty-panel .difficulty-opt.on{border-color:#e0c28d!important;background:#4b6340!important}\n.qh-footer{display:flex;align-items:center;justify-content:center;gap:8px;flex-wrap:wrap;margin:22px auto 0;padding-top:13px;border-top:1px solid rgba(196,154,91,.18);color:#a89b7f}\n.qh-footer span{font-size:11px;font-weight:900;color:#d6bd8e}.qh-footer i{width:3px;height:3px;border-radius:50%;background:#c49a5b}.qh-footer b{font:700 10px system-ui;color:#d9c49e}.qh-footer small{flex-basis:100%;text-align:center;font:700 7px system-ui;letter-spacing:2px;color:#778574}\n.qh-experience .brand-mark,.qh-experience .hero-cup,.qh-experience .step-progress{display:none!important}\n@media(max-width:390px){.start.neo-home.qh-experience{padding:10px 10px 22px!important}.qh-hero{min-height:112px;padding:17px 15px 23px!important}.qh-hero-seal{width:65px;height:65px;flex-basis:65px}.qh-hero h1{font-size:27px!important}.qh-panel{padding:14px 12px!important}.qh-mode-card{min-height:105px;padding:9px 7px!important}.qh-mode-card b{font-size:10px}.qh-games-grid{gap:6px}.qh-game-card{min-height:94px}.qh-avatar-pick{grid-template-columns:repeat(auto-fit,minmax(52px,1fr))!important}}\n@media(min-width:560px){.qh-profile-panel,.qh-choice-panel,.qh-game-panel,.qh-stake-section,.qh-difficulty-panel{padding:20px 22px!important}.qh-avatar-pick{grid-template-columns:repeat(6,1fr)!important}}\n"
for name in ("www/index.html", "www/game.html"):
    path = Path(name)
    src = path.read_text(encoding="utf-8")
    if "QH DESIGN PASS 106" in src:
        raise SystemExit(f"Design pass already present in {name}")
    if "</head>" not in src:
        raise SystemExit(f"Missing </head> in {name}")
    src = src.replace("</head>", '<style id="qh-design-pass-106">\n' + css + '\n</style>\n</head>', 1)
    path.write_text(src, encoding="utf-8")
print("QH Design Pass 106 applied to both app entry screens.")
